\if :{?names}
\else
\set names ''
\endif
\if :{?sample}
\else
\set sample 20
\endif
\if :{?seed}
\else
\set seed 'diet-gate-count'
\endif
\pset format unaligned
\pset fieldsep '\t'
\pset footer off
\if :{?audit}
\else
BEGIN READ ONLY;
WITH build AS (
    SELECT "Id", "Version", "CompletedAt", "LastCycleAt"
    FROM plan."DietGateBuild"
    WHERE "State" = 'active'
    ORDER BY "Id" DESC
    LIMIT 1
),
live AS (
    SELECT count(*) AS n FROM recipe."Recipe" WHERE NOT "IsDeleted"
),
decided AS (
    SELECT count(*) AS n
    FROM plan."DietRecipeState" s
    JOIN recipe."Recipe" r ON r."Id" = s."RecipeId" AND NOT r."IsDeleted"
    WHERE s."BuildId" = (SELECT "Id" FROM build)
),
sets AS (
    SELECT * FROM plan."DietGateSet" WHERE "BuildId" = (SELECT "Id" FROM build)
),
foods AS (
    SELECT f."SetId", count(*) AS n
    FROM plan."DietFoodFact" f
    WHERE f."SetId" IN (SELECT "Id" FROM sets) AND f."Verdict" = 1
    GROUP BY f."SetId"
),
flags AS (
    SELECT f."SetId",
           count(*) FILTER (WHERE f."Verdict" = 1 AND f."Reason" = 1) AS by_food,
           count(*) FILTER (WHERE f."Verdict" = 1 AND f."Reason" <> 1) AS by_text,
           count(*) FILTER (WHERE f."Verdict" = 2) AS unknown
    FROM plan."DietRecipeFlag" f
    JOIN recipe."Recipe" r ON r."Id" = f."RecipeId" AND NOT r."IsDeleted"
    JOIN plan."DietRecipeState" st ON st."RecipeId" = f."RecipeId" AND st."BuildId" = (SELECT "Id" FROM build)
    WHERE f."SetId" IN (SELECT "Id" FROM sets)
    GROUP BY f."SetId"
),
counted AS (
    SELECT ref."Name" AS type_name, s."RestrictionTypeId" AS type_id,
           CASE WHEN s."MinimumSeverity" >= 4 THEN 'severe' ELSE 'all' END AS reading,
           s."Severe" AS severe, s."State" AS state,
           coalesce(fo.n, 0) AS foods,
           coalesce(fl.by_food, 0) AS by_food,
           coalesce(fl.by_text, 0) AS by_text,
           coalesce(fl.unknown, 0) AS unknown,
           (SELECT n FROM live) - (SELECT n FROM decided) AS not_decided,
           CASE WHEN s."Severe" THEN coalesce(fl.unknown, 0) ELSE 0 END + (SELECT n FROM live) - (SELECT n FROM decided) AS held_for_unknown
    FROM sets s
    LEFT JOIN reference."Reference" ref ON ref."Id" = s."RestrictionTypeId"
    LEFT JOIN foods fo ON fo."SetId" = s."Id"
    LEFT JOIN flags fl ON fl."SetId" = s."Id"
)
SELECT 'build' AS kind, b."Id"::text AS type_name, b."Version" AS reading, NULL AS severe, NULL AS state, NULL AS foods, NULL AS by_food, NULL AS by_text,
       NULL AS unknown, NULL AS not_decided, NULL AS held, NULL AS held_for_unknown, (SELECT n FROM live)::text AS recipes, b."LastCycleAt"::text AS held_pct
FROM build b
UNION ALL
SELECT 'type', type_name || ' #' || type_id, reading, severe::text, state, foods::text, by_food::text, by_text::text, unknown::text, not_decided::text,
       (by_food + by_text + held_for_unknown)::text, held_for_unknown::text, (SELECT n FROM live)::text,
       round(100.0 * (by_food + by_text + held_for_unknown) / greatest((SELECT n FROM live), 1), 1)::text
FROM counted
ORDER BY 1, 2, 3;
ROLLBACK;
\q
\endif
